package com.example.project;

import android.os.Bundle;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import java.util.*;
public class CustomSpinnerActivity extends AppCompatActivity{@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_spinner);setTitle("CustomSpinner 예제");List<CustomItem> fruits=Arrays.asList(new CustomItem(R.drawable.apple,"사과"),new CustomItem(R.drawable.banana,"바나나"),new CustomItem(R.drawable.mango,"망고"));MySpinnerAdapter adapter=new MySpinnerAdapter(this,fruits);Spinner spinner=findViewById(R.id.spinner);spinner.setPrompt("과일을 고르세요.");spinner.setAdapter(adapter);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){boolean first=false;public void onItemSelected(AdapterView<?> p,View v,int pos,long id){if(first)Toast.makeText(CustomSpinnerActivity.this,fruits.get(pos).getName()+"는 맛있다",Toast.LENGTH_SHORT).show();else first=true;}public void onNothingSelected(AdapterView<?> p){}});findViewById(R.id.button).setOnClickListener(v->finish());}}
